import { describe, it, expect } from "vitest";

// Simulates a minimal package.json dependencies object
// to check whether an observability stack is present.

const APM_PACKAGES = [
  "@opentelemetry/api",
  "@opentelemetry/sdk-node",
  "dd-trace",
  "newrelic",
  "@honeycombio/opentelemetry-node",
];

const ERROR_TRACKING_PACKAGES = [
  "@sentry/node",
  "@sentry/browser",
  "@sentry/nextjs",
  "rollbar",
  "bugsnag",
  "@bugsnag/js",
];

function hasObservabilityStack(dependencies: Record<string, string>): {
  hasAPM: boolean;
  hasErrorTracking: boolean;
  isCompliant: boolean;
} {
  const deps = Object.keys(dependencies);
  const hasAPM = APM_PACKAGES.some((pkg) => deps.includes(pkg));
  const hasErrorTracking = ERROR_TRACKING_PACKAGES.some((pkg) =>
    deps.includes(pkg)
  );
  return {
    hasAPM,
    hasErrorTracking,
    isCompliant: hasAPM || hasErrorTracking,
  };
}

function simulateUnobservedError(
  deps: Record<string, string>
): { caught: boolean; traceable: boolean } {
  const { isCompliant } = hasObservabilityStack(deps);
  // Without observability, errors are silently swallowed in production
  try {
    throw new Error("Unhandled production error: database connection failed");
  } catch (e) {
    // Without an error tracker, this catch block has nowhere to report to
    return {
      caught: true,
      traceable: isCompliant, // only traceable if observability is wired up
    };
  }
}

describe("Observability stack detection", () => {
  it("demonstrates the foot-gun: no APM or error tracking means errors are invisible in production", () => {
    const bareMinimumDeps: Record<string, string> = {
      express: "^4.18.2",
      lodash: "^4.17.21",
      axios: "^1.4.0",
    };

    const result = hasObservabilityStack(bareMinimumDeps);

    expect(result.hasAPM).toBe(false);
    expect(result.hasErrorTracking).toBe(false);
    expect(result.isCompliant).toBe(false);

    // Errors happen but are not traceable
    const errorResult = simulateUnobservedError(bareMinimumDeps);
    expect(errorResult.caught).toBe(true);
    expect(errorResult.traceable).toBe(false); // <-- the foot-gun: error is lost
  });

  it("safe fix: adding Sentry provides error tracking visibility", () => {
    const depsWithSentry: Record<string, string> = {
      express: "^4.18.2",
      lodash: "^4.17.21",
      axios: "^1.4.0",
      "@sentry/node": "^7.64.0", // <-- fix applied
    };

    const result = hasObservabilityStack(depsWithSentry);

    expect(result.hasErrorTracking).toBe(true);
    expect(result.isCompliant).toBe(true);

    const errorResult = simulateUnobservedError(depsWithSentry);
    expect(errorResult.caught).toBe(true);
    expect(errorResult.traceable).toBe(true); // errors are now visible
  });

  it("safe fix: adding OpenTelemetry provides full APM tracing", () => {
    const depsWithOtel: Record<string, string> = {
      express: "^4.18.2",
      "@opentelemetry/api": "^1.4.1",
      "@opentelemetry/sdk-node": "^0.41.1",
    };

    const result = hasObservabilityStack(depsWithOtel);

    expect(result.hasAPM).toBe(true);
    expect(result.isCompliant).toBe(true);
  });

  it("safe fix: combining Sentry + OpenTelemetry gives full observability coverage", () => {
    const fullObservabilityDeps: Record<string, string> = {
      express: "^4.18.2",
      "@sentry/node": "^7.64.0",
      "@opentelemetry/api": "^1.4.1",
      "@opentelemetry/sdk-node": "^0.41.1",
    };

    const result = hasObservabilityStack(fullObservabilityDeps);

    expect(result.hasAPM).toBe(true);
    expect(result.hasErrorTracking).toBe(true);
    expect(result.isCompliant).toBe(true);
  });
});

import { describe, it, expect } from "vitest";

// Synthetic simulation of a minimal analytics client and event tracking.
// We recreate the foot-gun (no telemetry = silent feature adoption) and
// the safe fix (a lightweight analytics wrapper that captures key events).

// --- Foot-gun: no analytics instrumentation ---
function signupWithoutAnalytics(username: string): { user: string; events: string[] } {
  // User signs up but nothing is tracked — no visibility into adoption
  const user = username.trim();
  return { user, events: [] };
}

function activateFeatureWithoutAnalytics(featureName: string, events: string[]): void {
  // Feature is used but no event is emitted
  void featureName;
  void events;
}

// --- Safe fix: lightweight analytics wrapper tracking key lifecycle events ---
type AnalyticsEvent = {
  event: string;
  properties: Record<string, unknown>;
};

class AnalyticsClient {
  private queue: AnalyticsEvent[] = [];

  capture(event: string, properties: Record<string, unknown> = {}): void {
    this.queue.push({ event, properties });
  }

  getEvents(): AnalyticsEvent[] {
    return [...this.queue];
  }

  reset(): void {
    this.queue = [];
  }
}

function signupWithAnalytics(
  username: string,
  analytics: AnalyticsClient
): { user: string } {
  const user = username.trim();
  analytics.capture("signup", { username: user });
  return { user };
}

function activateFeatureWithAnalytics(
  featureName: string,
  analytics: AnalyticsClient
): void {
  analytics.capture("activation", { feature: featureName });
}

function recordFirstValueMoment(
  action: string,
  analytics: AnalyticsClient
): void {
  analytics.capture("first_value_moment", { action });
}

function recordRetentionSignal(
  userId: string,
  analytics: AnalyticsClient
): void {
  analytics.capture("retention", { userId });
}

function recordChurnSignal(
  userId: string,
  reason: string,
  analytics: AnalyticsClient
): void {
  analytics.capture("churn_signal", { userId, reason });
}

describe("Product analytics telemetry", () => {
  it("demonstrates the foot-gun: no events are captured without instrumentation", () => {
    const result = signupWithoutAnalytics("alice");
    expect(result.user).toBe("alice");
    // No events tracked — zero visibility into user journeys
    expect(result.events).toHaveLength(0);

    const events: string[] = [];
    activateFeatureWithoutAnalytics("dark-mode", events);
    // Still nothing tracked — feature adoption is invisible
    expect(events).toHaveLength(0);
  });

  it("safe fix: captures signup and activation events via analytics client", () => {
    const analytics = new AnalyticsClient();

    const { user } = signupWithAnalytics("bob", analytics);
    expect(user).toBe("bob");

    const eventsAfterSignup = analytics.getEvents();
    expect(eventsAfterSignup).toHaveLength(1);
    expect(eventsAfterSignup[0].event).toBe("signup");
    expect(eventsAfterSignup[0].properties.username).toBe("bob");

    activateFeatureWithAnalytics("dark-mode", analytics);
    const eventsAfterActivation = analytics.getEvents();
    expect(eventsAfterActivation).toHaveLength(2);
    expect(eventsAfterActivation[1].event).toBe("activation");
    expect(eventsAfterActivation[1].properties.feature).toBe("dark-mode");
  });

  it("safe fix: captures the 5 key lifecycle events recommended by PostHog guidance", () => {
    const analytics = new AnalyticsClient();

    signupWithAnalytics("carol", analytics);
    activateFeatureWithAnalytics("onboarding-wizard", analytics);
    recordFirstValueMoment("created-first-project", analytics);
    recordRetentionSignal("user-carol", analytics);
    recordChurnSignal("user-carol", "too-expensive", analytics);

    const events = analytics.getEvents();
    expect(events).toHaveLength(5);

    const eventNames = events.map((e) => e.event);
    expect(eventNames).toContain("signup");
    expect(eventNames).toContain("activation");
    expect(eventNames).toContain("first_value_moment");
    expect(eventNames).toContain("retention");
    expect(eventNames).toContain("churn_signal");

    const churnEvent = events.find((e) => e.event === "churn_signal");
    expect(churnEvent?.properties.reason).toBe("too-expensive");
  });

  it("safe fix: analytics client is isolated — reset clears the queue between sessions", () => {
    const analytics = new AnalyticsClient();

    signupWithAnalytics("dave", analytics);
    expect(analytics.getEvents()).toHaveLength(1);

    analytics.reset();
    expect(analytics.getEvents()).toHaveLength(0);

    activateFeatureWithAnalytics("export-csv", analytics);
    expect(analytics.getEvents()).toHaveLength(1);
    expect(analytics.getEvents()[0].event).toBe("activation");
  });
});

import { describe, it, expect } from "vitest";

// Synthetic in-memory rate limiter implementations

// --- Foot-gun: No rate limiting on auth endpoint ---
function createUnprotectedAuthHandler() {
  const failedAttempts: Record<string, number> = {};

  return function handleLogin(ip: string, username: string, password: string): { success: boolean; error?: string } {
    // Simulates a DB of valid credentials
    const validCredentials: Record<string, string> = { admin: "s3cr3t" };

    if (validCredentials[username] === password) {
      return { success: true };
    }
    failedAttempts[ip] = (failedAttempts[ip] ?? 0) + 1;
    return { success: false, error: "Invalid credentials" };
  };
}

// --- Safe fix: Rate-limited auth handler with account locking ---
function createRateLimitedAuthHandler({
  maxAttemptsPerMinute = 5,
  lockoutThreshold = 10,
}: {
  maxAttemptsPerMinute?: number;
  lockoutThreshold?: number;
} = {}) {
  const ipAttempts: Record<string, { count: number; windowStart: number }> = {};
  const accountFailures: Record<string, number> = {};
  const lockedAccounts: Set<string> = new Set();

  return function handleLogin(
    ip: string,
    username: string,
    password: string,
    nowMs: number = Date.now()
  ): { success: boolean; error?: string; rateLimited?: boolean; locked?: boolean } {
    // Per-IP rate limiting (sliding window, 60s)
    const ipRecord = ipAttempts[ip];
    if (!ipRecord || nowMs - ipRecord.windowStart > 60_000) {
      ipAttempts[ip] = { count: 1, windowStart: nowMs };
    } else {
      ipAttempts[ip].count += 1;
    }

    if (ipAttempts[ip].count > maxAttemptsPerMinute) {
      return { success: false, error: "Too many requests", rateLimited: true };
    }

    // Account lockout
    if (lockedAccounts.has(username)) {
      return { success: false, error: "Account locked", locked: true };
    }

    const validCredentials: Record<string, string> = { admin: "s3cr3t" };

    if (validCredentials[username] === password) {
      accountFailures[username] = 0;
      return { success: true };
    }

    accountFailures[username] = (accountFailures[username] ?? 0) + 1;
    if (accountFailures[username] >= lockoutThreshold) {
      lockedAccounts.add(username);
    }

    return { success: false, error: "Invalid credentials" };
  };
}

describe("Auth Endpoints Rate Limiting", () => {
  it("demonstrates the foot-gun: unprotected handler allows unlimited brute-force attempts", () => {
    const handleLogin = createUnprotectedAuthHandler();
    const ip = "192.168.1.1";
    const results: boolean[] = [];

    // Simulate 50 rapid brute-force attempts — all are processed without restriction
    for (let i = 0; i < 50; i++) {
      const res = handleLogin(ip, "admin", `wrong-password-${i}`);
      results.push(res.success);
    }

    // Every attempt reaches the auth logic — none are blocked
    const blockedCount = results.filter((r) => r === true).length;
    expect(blockedCount).toBe(0); // none succeeded (wrong passwords)
    // But critically, ALL 50 attempts were processed — no rate limiting occurred
    expect(results).toHaveLength(50);

    // Even a correct password attempt on the 51st try goes through unimpeded
    const successAttempt = handleLogin(ip, "admin", "s3cr3t");
    expect(successAttempt.success).toBe(true); // brute-force would eventually find this
  });

  it("safe fix: rate-limited handler blocks excessive attempts per IP within a time window", () => {
    const handleLogin = createRateLimitedAuthHandler({ maxAttemptsPerMinute: 5, lockoutThreshold: 10 });
    const ip = "10.0.0.1";
    const baseTime = 1_000_000;
    const results: Array<{ success: boolean; rateLimited?: boolean }> = [];

    // First 5 attempts within the same minute window — allowed
    for (let i = 0; i < 5; i++) {
      const res = handleLogin(ip, "admin", `wrong-${i}`, baseTime + i * 100);
      results.push(res);
    }

    // 6th attempt within the same window — should be rate limited
    const blockedAttempt = handleLogin(ip, "admin", "wrong-6", baseTime + 600);
    expect(blockedAttempt.rateLimited).toBe(true);
    expect(blockedAttempt.success).toBe(false);
    expect(blockedAttempt.error).toBe("Too many requests");

    // Even the correct password is blocked when rate limit is exceeded
    const blockedCorrect = handleLogin(ip, "admin", "s3cr3t", baseTime + 700);
    expect(blockedCorrect.rateLimited).toBe(true);
    expect(blockedCorrect.success).toBe(false);

    // After the window resets (>60s later), login is allowed again
    const afterWindow = handleLogin(ip, "admin", "s3cr3t", baseTime + 70_000);
    expect(afterWindow.success).toBe(true);
    expect(afterWindow.rateLimited).toBeUndefined();
  });

  it("safe fix: account locking triggers after exceeding failure threshold", () => {
    const handleLogin = createRateLimitedAuthHandler({ maxAttemptsPerMinute: 100, lockoutThreshold: 10 });
    const baseTime = 2_000_000;

    // Use different IPs to avoid IP-level rate limiting, focus on account lockout
    for (let i = 0; i < 10; i++) {
      const res = handleLogin(`10.0.${i}.1`, "admin", `wrong-${i}`, baseTime + i * 1000);
      expect(res.success).toBe(false);
      if (i < 9) {
        expect(res.locked).toBeUndefined();
      }
    }

    // After 10 failures, account should be locked
    const lockedAttempt = handleLogin("10.0.99.1", "admin", "s3cr3t", baseTime + 20_000);
    expect(lockedAttempt.locked).toBe(true);
    expect(lockedAttempt.success).toBe(false);
    expect(lockedAttempt.error).toBe("Account locked");
  });

  it("safe fix: different IPs have independent rate limit counters", () => {
    const handleLogin = createRateLimitedAuthHandler({ maxAttemptsPerMinute: 5 });
    const baseTime = 3_000_000;

    // Exhaust rate limit for IP A
    for (let i = 0; i <= 5; i++) {
      handleLogin("1.1.1.1", "admin", `wrong-${i}`, baseTime + i * 10);
    }
    const ipABlocked = handleLogin("1.1.1.1", "admin", "wrong-extra", baseTime + 100);
    expect(ipABlocked.rateLimited).toBe(true);

    // IP B should still be allowed
    const ipBAllowed = handleLogin("2.2.2.2", "admin", "s3cr3t", baseTime + 100);
    expect(ipBAllowed.success).toBe(true);
    expect(ipBAllowed.rateLimited).toBeUndefined();
  });
});
